import numpy as np

def select_next_node(current_node: int, depot: int, unvisited_nodes: np.ndarray, rest_capacity: np.ndarray, demands: np.ndarray, distance_matrix: np.ndarray) -> int:
    # Convert rest_capacity to a scalar if necessary
    if isinstance(rest_capacity, np.ndarray):
        rest_capacity = rest_capacity.item()

    best_score = -np.inf
    next_node = None
    d_current_depot = distance_matrix[current_node][depot]

    for node in unvisited_nodes:
        node = int(node)
        if demands[node] > rest_capacity:
            continue

        dist_cur_node = distance_matrix[current_node][node]
        dist_node_depot = distance_matrix[node][depot]
        # Additional distance if we visit node and then go to depot vs going directly to depot
        additional = dist_cur_node + dist_node_depot - d_current_depot

        # Handle non-positive additional distance as infinite savings (direct path case)
        if additional <= 0:
            score = np.inf
        else:
            score = demands[node] / additional

        # Deterministic tie-breaking: higher score, then higher demand, then lower node id
        if next_node is None or score > best_score or (
            score == best_score and demands[node] > demands[next_node]
        ) or (
            score == best_score and demands[node] == demands[next_node] and node < next_node
        ):
            best_score = score
            next_node = node

    return next_node if next_node is not None else -1

