import numpy as np

def select_next_node(current_node: int, depot: int, unvisited_nodes: np.ndarray, rest_capacity: np.ndarray, current_time: np.ndarray,
                     demands: np.ndarray, distance_matrix: np.ndarray, time_windows: np.ndarray) -> int:
    best_node = None
    best_score = float('inf')
    alpha = 1.0  # weight for slack term; tune if needed

    for node in unvisited_nodes:
        # Feasibility: capacity
        if demands[node] > rest_capacity:
            continue
        # Feasibility: time window
        travel = distance_matrix[current_node, node]
        arrival = current_time + travel
        if arrival > time_windows[node, 1]:
            continue  # too late
        # If arrival before earliest, we wait, so arrival becomes earliest (but travel time still considered)
        if arrival < time_windows[node, 0]:
            arrival = time_windows[node, 0]
        slack = time_windows[node, 1] - arrival
        # Score: distance + weight * slack (penalize large slack, i.e., prefer urgent nodes)
        # But we also want to keep distance low; alpha=0.5 typical
        score = travel + 0.5 * slack
        if score < best_score:
            best_score = score
            best_node = node
    # If no feasible, fallback: nearest feasible by capacity (ignore time window)
    if best_node is None:
        best_node = unvisited_nodes[0]
        best_dist = np.inf
        for i in unvisited_nodes:
            if demands[i] <= rest_capacity:
                d = distance_matrix[current_node, i]
                if d < best_dist:
                    best_dist = d
                    best_node = i
    return int(best_node)
